//! Unicode character database for the RPython runtime (CPython 3.15 semantics).
//!
//! All data lives in static tables generated by `crates/unicode/gen` from the
//! UCD files in `crates/unicode/data/`; there is no start-up cost.
//!
//! * Character predicates and case mappings used by `str` methods live at the
//!   crate root (`is_alpha`, `to_upper_full`, ...).
//! * The `unicodedata` module functionality is exposed through [`Ucd`]
//!   (`Ucd::Current` is the module itself, `Ucd::V3_2_0` is
//!   `unicodedata.ucd_3_2_0`), plus a few current-version-only free functions
//!   (`grapheme_cluster_break`, `block`, ...).
//! * Name lookup for `\N{...}` escapes: [`lookup_name`].
//!
//! Code points are passed as `u32`; values above 0x10FFFF are treated like
//! U+10FFFF (an unassigned noncharacter).

#![forbid(unsafe_code)]

mod tables {
    pub mod db;
    pub mod names;
    pub mod v320;
}

mod grapheme;
mod names;
mod normalize;
mod ucd;

pub use grapheme::{
    extended_pictographic, grapheme_cluster_break, indic_conjunct_break, next_grapheme_break,
    next_grapheme_break_by, Graphemes,
};
pub use names::{lookup_name, name, Lookup, NAME_MAX_LEN};
pub use normalize::{is_normalized, normalize, Form};
pub use ucd::Ucd;

use tables::db::*;

/// The Unicode version of the current database (`unicodedata.unidata_version`).
pub const UNIDATA_VERSION: &str = tables::db::UNIDATA_VERSION;

// ---------------------------------------------------------------------------
// Record types used by the generated tables
// ---------------------------------------------------------------------------

#[derive(Debug, Clone, Copy)]
pub(crate) struct TypeRecord {
    pub flags: u16,
    /// Simple mappings as deltas from the code point.
    pub upper: i32,
    pub lower: i32,
    pub title: i32,
    /// 0xFF: none.
    pub decimal: u8,
    pub digit: u8,
    /// Index into NUMERIC_VALUES, 0xFFFF: none.
    pub numeric: u16,
    /// Offset into SPECIAL_CASE (valid if EXTENDED_CASE is set).
    pub special: u16,
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct DbRecord {
    pub category: u8,
    pub combining: u8,
    pub bidi: u8,
    pub eaw: u8,
    pub flags: u8,
    pub gcb: u8,
    pub incb: u8,
}

/// Unicode 3.2.0 values of a character that is assigned in 3.2.0 and whose
/// properties differ from the current database.
#[derive(Debug, Clone, Copy)]
pub(crate) struct ChangeRecord {
    pub category: u8,
    pub bidi: u8,
    pub eaw: u8,
    pub mirrored: bool,
    pub decimal: u8,
    /// NaN: no numeric value.
    pub numeric: f64,
}

// TypeRecord flags (must match gen/src/main.rs)
pub(crate) const ALPHA: u16 = 1 << 0;
pub(crate) const DECIMAL: u16 = 1 << 1;
pub(crate) const DIGIT: u16 = 1 << 2;
pub(crate) const NUMERIC: u16 = 1 << 3;
pub(crate) const LOWER: u16 = 1 << 4;
pub(crate) const UPPER: u16 = 1 << 5;
pub(crate) const TITLE: u16 = 1 << 6;
pub(crate) const CASED: u16 = 1 << 7;
pub(crate) const CASE_IGNORABLE: u16 = 1 << 8;
pub(crate) const SPACE: u16 = 1 << 9;
pub(crate) const LINEBREAK: u16 = 1 << 10;
pub(crate) const PRINTABLE: u16 = 1 << 11;
pub(crate) const XID_START: u16 = 1 << 12;
pub(crate) const XID_CONTINUE: u16 = 1 << 13;
pub(crate) const EXTENDED_CASE: u16 = 1 << 14;

// DbRecord flags (must match gen/src/main.rs)
pub(crate) const MIRRORED: u8 = 1 << 0;
pub(crate) const NFD_NO: u8 = 1 << 1;
pub(crate) const NFKD_NO: u8 = 1 << 2;
pub(crate) const NFC_NO: u8 = 1 << 3;
pub(crate) const NFC_MAYBE: u8 = 1 << 4;
pub(crate) const NFKC_NO: u8 = 1 << 5;
pub(crate) const NFKC_MAYBE: u8 = 1 << 6;
pub(crate) const EXT_PICT: u8 = 1 << 7;

#[inline(always)]
pub(crate) fn type_record(c: u32) -> &'static TypeRecord {
    &TYPE_RECORDS[ctype_index(c) as usize]
}

#[inline(always)]
pub(crate) fn db_record(c: u32) -> &'static DbRecord {
    &DB_RECORDS[db_index(c) as usize]
}

#[inline(always)]
fn flags(c: u32) -> u16 {
    type_record(c).flags
}

// ---------------------------------------------------------------------------
// str predicates
// ---------------------------------------------------------------------------

/// `str.isalpha` for one character: general category Lm, Lt, Lu, Ll or Lo.
#[inline]
pub fn is_alpha(c: u32) -> bool {
    flags(c) & ALPHA != 0
}

/// `str.isdecimal`: the character has a decimal digit value (UnicodeData field 6).
#[inline]
pub fn is_decimal(c: u32) -> bool {
    flags(c) & DECIMAL != 0
}

/// `str.isdigit`: the character has a digit value (UnicodeData field 7).
#[inline]
pub fn is_digit(c: u32) -> bool {
    flags(c) & DIGIT != 0
}

/// `str.isnumeric`: the character has a numeric value (UnicodeData field 8 or Unihan).
#[inline]
pub fn is_numeric(c: u32) -> bool {
    flags(c) & NUMERIC != 0
}

/// `str.isalnum`: alpha, decimal, digit or numeric.
#[inline]
pub fn is_alnum(c: u32) -> bool {
    flags(c) & (ALPHA | DECIMAL | DIGIT | NUMERIC) != 0
}

/// `str.isspace`: bidirectional class WS, B or S, or general category Zs.
#[inline]
pub fn is_space(c: u32) -> bool {
    if c < 128 {
        return matches!(c, 0x09..=0x0D | 0x1C..=0x20);
    }
    flags(c) & SPACE != 0
}

/// `str.isprintable`: not in categories C* / Z*, except U+0020 SPACE.
#[inline]
pub fn is_printable(c: u32) -> bool {
    flags(c) & PRINTABLE != 0
}

/// `Lowercase` derived property (used by `str.islower`).
#[inline]
pub fn is_lowercase(c: u32) -> bool {
    flags(c) & LOWER != 0
}

/// `Uppercase` derived property (used by `str.isupper`).
#[inline]
pub fn is_uppercase(c: u32) -> bool {
    flags(c) & UPPER != 0
}

/// General category Lt (used by `str.istitle`).
#[inline]
pub fn is_titlecase(c: u32) -> bool {
    flags(c) & TITLE != 0
}

/// `Cased` derived property.
#[inline]
pub fn is_cased(c: u32) -> bool {
    flags(c) & CASED != 0
}

/// `Case_Ignorable` derived property.
#[inline]
pub fn is_case_ignorable(c: u32) -> bool {
    flags(c) & CASE_IGNORABLE != 0
}

/// `XID_Start` derived property (`str.isidentifier` additionally allows `_`
/// as first character).
#[inline]
pub fn is_xid_start(c: u32) -> bool {
    flags(c) & XID_START != 0
}

/// `XID_Continue` derived property.
#[inline]
pub fn is_xid_continue(c: u32) -> bool {
    flags(c) & XID_CONTINUE != 0
}

/// Characters `str.splitlines` splits on: \n \v \f \r \x1c \x1d \x1e \x85
/// U+2028 U+2029.
#[inline]
pub fn is_linebreak(c: u32) -> bool {
    flags(c) & LINEBREAK != 0
}

/// `str.isidentifier` on a sequence of code points (no NFKC requirement:
/// identifiers in source are NFKC-normalized by the tokenizer).
pub fn is_identifier(s: &[u32]) -> bool {
    match s.split_first() {
        None => false,
        Some((&first, rest)) => {
            (first == '_' as u32 || is_xid_start(first)) && rest.iter().all(|&c| is_xid_continue(c))
        }
    }
}

// ---------------------------------------------------------------------------
// numeric values
// ---------------------------------------------------------------------------

/// Decimal digit value (`unicodedata.decimal`, `int()` parsing).
#[inline]
pub fn to_decimal(c: u32) -> Option<u32> {
    let r = type_record(c);
    if r.decimal == 0xFF {
        None
    } else {
        Some(r.decimal as u32)
    }
}

/// Digit value (`unicodedata.digit`).
#[inline]
pub fn to_digit(c: u32) -> Option<u32> {
    let r = type_record(c);
    if r.digit == 0xFF {
        None
    } else {
        Some(r.digit as u32)
    }
}

/// Numeric value (`unicodedata.numeric`), including fractions and Unihan values.
#[inline]
pub fn to_numeric(c: u32) -> Option<f64> {
    let r = type_record(c);
    if r.numeric == 0xFFFF {
        None
    } else {
        Some(NUMERIC_VALUES[r.numeric as usize])
    }
}

// ---------------------------------------------------------------------------
// case mapping
// ---------------------------------------------------------------------------

/// Simple (1:1) lowercase mapping from UnicodeData.txt.
#[inline]
pub fn to_lower_simple(c: u32) -> u32 {
    (c as i32 + type_record(c).lower) as u32
}

/// Simple (1:1) uppercase mapping from UnicodeData.txt.
#[inline]
pub fn to_upper_simple(c: u32) -> u32 {
    (c as i32 + type_record(c).upper) as u32
}

/// Simple (1:1) titlecase mapping from UnicodeData.txt (defaults to the
/// uppercase mapping).
#[inline]
pub fn to_title_simple(c: u32) -> u32 {
    (c as i32 + type_record(c).title) as u32
}

const SPECIAL_LOWER: usize = 0;
const SPECIAL_TITLE: usize = 1;
const SPECIAL_UPPER: usize = 2;
const SPECIAL_FOLD: usize = 3;

#[inline]
fn special(off: u16, which: usize, out: &mut [u32; 3]) -> usize {
    let off = off as usize;
    let h = SPECIAL_CASE[off] as usize;
    let mut start = off + 1;
    for k in 0..which {
        start += (h >> (4 * k)) & 0xF;
    }
    let n = (h >> (4 * which)) & 0xF;
    for i in 0..n {
        out[i] = SPECIAL_CASE[start + i] as u32;
    }
    n
}

#[inline]
fn full_mapping(c: u32, which: usize, out: &mut [u32; 3]) -> usize {
    let r = type_record(c);
    if r.flags & EXTENDED_CASE != 0 {
        special(r.special, which, out)
    } else {
        let delta = match which {
            SPECIAL_LOWER | SPECIAL_FOLD => r.lower,
            SPECIAL_TITLE => r.title,
            _ => r.upper,
        };
        out[0] = (c as i32 + delta) as u32;
        1
    }
}

/// Full lowercase mapping (SpecialCasing.txt unconditional mappings).  Does
/// not apply the Final_Sigma rule; see [`is_final_sigma`] / [`lower_full_at`].
/// Returns the number of code points written (1..=3).
#[inline]
pub fn to_lower_full(c: u32, out: &mut [u32; 3]) -> usize {
    full_mapping(c, SPECIAL_LOWER, out)
}

/// Full uppercase mapping, e.g. 'ß' -> "SS", 'ﬁ' -> "FI".
#[inline]
pub fn to_upper_full(c: u32, out: &mut [u32; 3]) -> usize {
    full_mapping(c, SPECIAL_UPPER, out)
}

/// Full titlecase mapping, e.g. 'ﬁ' -> "Fi".
#[inline]
pub fn to_title_full(c: u32, out: &mut [u32; 3]) -> usize {
    full_mapping(c, SPECIAL_TITLE, out)
}

/// Full case folding (CaseFolding.txt statuses C and F; falls back to the
/// lowercase mapping), as used by `str.casefold`.
#[inline]
pub fn casefold_full(c: u32, out: &mut [u32; 3]) -> usize {
    full_mapping(c, SPECIAL_FOLD, out)
}

/// Whether the character has a non-trivial full case mapping or folding
/// (i.e. one of the `*_full` functions can produce more than one code point,
/// or folding differs from lowercasing).
#[inline]
pub fn has_special_casing(c: u32) -> bool {
    flags(c) & EXTENDED_CASE != 0
}

/// Final_Sigma context test for U+03A3 as implemented by CPython's
/// `str.lower`: `before` iterates the characters preceding the sigma in
/// reverse order, `after` the characters following it.  Returns true if the
/// sigma must become U+03C2 (final small sigma).
pub fn is_final_sigma<B, A>(before: B, after: A) -> bool
where
    B: IntoIterator<Item = u32>,
    A: IntoIterator<Item = u32>,
{
    let mut final_sigma = false;
    for c in before {
        if !is_case_ignorable(c) {
            final_sigma = is_cased(c);
            break;
        }
    }
    if !final_sigma {
        return false;
    }
    for c in after {
        if !is_case_ignorable(c) {
            return !is_cased(c);
        }
    }
    true
}

/// `str.lower` mapping of `s[i]` including the Final_Sigma rule.
pub fn lower_full_at(s: &[u32], i: usize, out: &mut [u32; 3]) -> usize {
    let c = s[i];
    if c == 0x3A3 {
        out[0] = if is_final_sigma(s[..i].iter().rev().copied(), s[i + 1..].iter().copied()) {
            0x3C2
        } else {
            0x3C3
        };
        1
    } else {
        to_lower_full(c, out)
    }
}

// ---------------------------------------------------------------------------
// Current-database property accessors (also available through `Ucd`)
// ---------------------------------------------------------------------------

/// General category, e.g. "Lu" (`unicodedata.category`).
#[inline]
pub fn category(c: u32) -> &'static str {
    CATEGORY_NAMES[db_record(c).category as usize]
}

/// Bidirectional class, e.g. "L" (`unicodedata.bidirectional`).
#[inline]
pub fn bidirectional(c: u32) -> &'static str {
    BIDI_NAMES[db_record(c).bidi as usize]
}

/// Canonical combining class (`unicodedata.combining`).
#[inline]
pub fn combining(c: u32) -> u8 {
    db_record(c).combining
}

/// East Asian width, e.g. "W" (`unicodedata.east_asian_width`).
#[inline]
pub fn east_asian_width(c: u32) -> &'static str {
    EAW_NAMES[db_record(c).eaw as usize]
}

/// Bidi_Mirrored property (`unicodedata.mirrored`).
#[inline]
pub fn mirrored(c: u32) -> bool {
    db_record(c).flags & MIRRORED != 0
}

/// Block name, "No_Block" if none (`unicodedata.block`).
pub fn block(c: u32) -> &'static str {
    let i = BLOCKS.partition_point(|&(_, end, _)| end < c);
    match BLOCKS.get(i) {
        Some(&(start, _, name)) if start <= c => name,
        _ => "No_Block",
    }
}

pub(crate) const S_BASE: u32 = 0xAC00;
pub(crate) const L_BASE: u32 = 0x1100;
pub(crate) const V_BASE: u32 = 0x1161;
pub(crate) const T_BASE: u32 = 0x11A7;
pub(crate) const L_COUNT: u32 = 19;
pub(crate) const V_COUNT: u32 = 21;
pub(crate) const T_COUNT: u32 = 28;
pub(crate) const N_COUNT: u32 = V_COUNT * T_COUNT;
pub(crate) const S_COUNT: u32 = L_COUNT * N_COUNT;

/// Raw decomposition mapping: (tag, code points).  The tag is "" for
/// canonical mappings, otherwise e.g. "<compat>".  Hangul syllables are
/// decomposed algorithmically (into L V or LV T... as full L V T).
pub fn decomposition_mapping(c: u32) -> Option<(&'static str, DecompSeq)> {
    if (S_BASE..S_BASE + S_COUNT).contains(&c) {
        let s = c - S_BASE;
        let l = L_BASE + s / N_COUNT;
        let v = V_BASE + (s % N_COUNT) / T_COUNT;
        let t = T_BASE + s % T_COUNT;
        let seq = if t == T_BASE { DecompSeq::Hangul([l, v, 0], 2) } else { DecompSeq::Hangul([l, v, t], 3) };
        return Some(("", seq));
    }
    let (tag, seq) = raw_decomposition(c)?;
    Some((DECOMP_TAGS[tag as usize], DecompSeq::Table(seq)))
}

/// A decomposition sequence (see [`decomposition_mapping`]).
#[derive(Debug, Clone, Copy)]
pub enum DecompSeq {
    Table(&'static [u32]),
    Hangul([u32; 3], usize),
}

impl DecompSeq {
    pub fn as_slice(&self) -> &[u32] {
        match self {
            DecompSeq::Table(s) => s,
            DecompSeq::Hangul(a, n) => &a[..*n],
        }
    }
}

/// (tag index, code points) from the decomposition table (no Hangul).
#[inline]
pub(crate) fn raw_decomposition(c: u32) -> Option<(u32, &'static [u32])> {
    let i = decomp_index(c) as usize;
    if i == 0 {
        return None;
    }
    let h = DECOMP_DATA[i];
    let n = (h & 0xFF) as usize;
    Some((h >> 8, &DECOMP_DATA[i + 1..i + 1 + n]))
}

/// `unicodedata.decomposition` string, e.g. "<compat> 0020 0301"; empty if none.
pub fn decomposition(c: u32) -> String {
    let mut s = String::new();
    if let Some((tag, seq)) = decomposition_mapping(c) {
        s.push_str(tag);
        for &d in seq.as_slice() {
            if !s.is_empty() {
                s.push(' ');
            }
            use std::fmt::Write;
            let _ = write!(s, "{d:04X}");
        }
    }
    s
}

